<?php $address=json_decode($order['address_json'],true); ?><section class="container-wide section"><div class="order-confirmation"><span class="confirmation-icon"><?= $order['payment_status']==='paid'?'✓':'♧' ?></span><span class="eyebrow"><?= $order['payment_status']==='paid'?'PAYMENT CONFIRMED':'YOUR ORDER IS SAVED' ?></span><h1><?= match($order['status']) {'Delivered'=>'Your order has been delivered.','Cancelled'=>'Your order has been cancelled.','Packed'=>'Your jars are packed.','Shipped'=>'Your order is on its way.','Out for delivery'=>'Your order is out for delivery.',default=>'Thank you for choosing Prakshi.'} ?></h1><p>Order <?= e($order['number']) ?> · <?= e($order['status']) ?> · Payment <?= e($order['payment_status']) ?></p></div><?php require ROOT.'/app/Views/store/order-tracking.php'; ?><div class="checkout-grid"><div class="panel"><h2>Your jars.</h2><?php foreach($items as $i): ?><div class="summary-line"><span><?= e($i['name']) ?> · <?= e($i['variant']) ?> × <?= $i['quantity'] ?></span><strong><?= money($i['price']*$i['quantity']) ?></strong></div><?php endforeach ?><?php if($order['tracking']): ?><div class="alert alert-success mt-3">Shipment tracking reference: <?= e($order['tracking']) ?></div><?php endif ?><hr><h3>Delivery address</h3><p><?= e($address['name']) ?><br><?= e($address['address']) ?><br><?= e($address['city'].', '.$address['state'].' '.$address['pincode']) ?><br><?= e($address['mobile']) ?></p><div class="d-flex gap-3 flex-wrap no-print"><a class="btn btn-outline-primary" href="<?= e(url('invoice',['id'=>$order['id']])) ?>">Download invoice PDF</a><button class="btn btn-outline-primary" onclick="window.print()">Print order summary</button><form action="<?= e(url('reorder')) ?>" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><button class="btn btn-outline-primary">Order these again</button></form></div></div><aside class="panel order-summary"><h2>Order summary</h2><?php $totals=$order;require ROOT.'/app/Views/store/summary.php'; ?><p><?= $order['payment_method']==='cod'?'Cash on delivery':'Online payment via Razorpay' ?></p><?php if($order['payment_method']==='razorpay' && in_array($order['payment_status'],['pending','failed']) && $order['status']!=='Cancelled'): ?><button class="btn btn-primary w-100" id="pay-now" data-order="<?= $order['id'] ?>">Pay securely →</button><p class="small muted mt-2">Payment will be confirmed only after verification.</p><script src="https://checkout.razorpay.com/v1/checkout.js"></script><?php endif ?><a href="<?= e(url('account')) ?>" class="text-link">View my orders →</a></aside></div></section>
